# Surah Al-Mujadala (chapter 58) — part 2: ayat 13-22 (IDs 5117-5126)
SURAH = 58

ENTRIES = {
5117: (
"کیا تم اپنی سرگوشیوں سے پہلے صدقات پیش کرنے سے ڈر گئے؟ پس جب تم نے نہیں کیا اور اللہ نے تمہاری توبہ قبول کر لی تو نماز قائم کرو اور زکوٰۃ دو اور اللہ اور اس کے رسول کی اطاعت کرو — اور اللہ جو تم کرتے ہو اس سے باخبر ہے",
"""۱۔ سرگوشی اور صدقہ کا حکم — أشفقتم أن تقدموا بین یدي نجواکم صدقات؛ فإذ لم تفعلوا و تاب الله علیکم فأقیموا الصلاة و آتوا الزکاة و أطیعوا الله و رسوله؛ و الله خبیر بما تعملون۔
۲۔ ’’أَأَشْفَقْتُمْ أَن تُقَدِّمُوا بَيْنَ يَدَيْ نَجْوَاكُمْ صَدَقَاتٍ فَإِذْ لَمْ تَفْعَلُوا وَتَابَ اللَّهُ عَلَيْكُمْ فَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا اللَّهَ وَرَسُولَهُ وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ‘‘ — کیا تم اپنی سرگوشیوں سے پہلے صدقات پیش کرنے سے ڈر گئے؟ پس جب تم نے نہیں کیا اور اللہ نے تمہاری توبہ قبول کر لی تو نماز قائم کرو اور زکوٰۃ دو اور اللہ اور اس کے رسول کی اطاعت کرو — اور اللہ جو تم کرتے ہو اس سے باخبر ہے — یعنی کیا تم اپنی سرگوشیوں سے پہلے صدقات پیش کرنے سے ڈر گئے پس جب تم نے نہیں کیا اور اللہ نے تمہاری توبہ قبول کر لی تو نماز قائم کرو اور زکوٰۃ دو اور اللہ اور اس کے رسول کی اطاعت کرو اور اللہ جو تم کرتے ہو اس سے باخبر ہے۔
۳۔ عملی سبق: نماز، زکوٰۃ اور اطاعت کرو؛ اللہ سے ڈرو۔"""
),
5118: (
"کیا تو نے دیکھا انہیں جنہوں نے ایسی قوم کو دوست بنایا جن پر اللہ نے غضب کیا — نہ وہ تم سے ہیں نہ ان سے — اور وہ جھوٹی قسمیں کھاتے ہیں اور وہ جانتے ہیں",
"""۱۔ منافقین — ألم تر إلی الذین تولّوا قومًا غضب الله علیهم؛ ما هم منکم و لا منهم؛ و یحلفون علی الکذب و هم یعلمون۔
۲۔ ’’أَلَمْ تَرَ إِلَى الَّذِينَ تَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى الْكَذِبِ وَهُمْ يَعْلَمُونَ‘‘ — کیا تو نے دیکھا انہیں جنہوں نے ایسی قوم کو دوست بنایا جن پر اللہ نے غضب کیا — نہ وہ تم سے ہیں نہ ان سے — اور وہ جھوٹی قسمیں کھاتے ہیں اور وہ جانتے ہیں — یعنی کیا تو نے دیکھا انہیں جنہوں نے ایسی قوم کو دوست بنایا جن پر اللہ نے غضب کیا نہ وہ تم سے ہیں نہ ان سے اور وہ جھوٹی قسمیں کھاتے ہیں اور وہ جانتے ہیں۔
۳۔ عملی سبق: منافقین سے دوستی نہ کرو؛ اللہ سے ڈرو۔"""
),
5119: (
"اللہ نے ان کے لیے سخت عذاب تیار کیا ہے — بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں",
"""۱۔ عذاب — أعدّ الله لهم عذابًا شدیدًا؛ إنهم ساء ما کانوا یعملون۔
۲۔ ’’أَعَدَّ اللَّهُ لَهُمْ عَذَابًا شَدِيدًا إِنَّهُمْ سَاءَ مَا كَانُوا يَعْمَلُونَ‘‘ — اللہ نے ان کے لیے سخت عذاب تیار کیا ہے — بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں — یعنی اللہ نے ان کے لیے سخت عذاب تیار کیا ہے بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں۔
۳۔ عملی سبق: گناہ چھوڑو؛ اللہ سے ڈرو۔"""
),
5120: (
"انہوں نے اپنی قسموں کو ڈھال بنایا اور اللہ کے راستے سے روکا پس ان کے لیے ذلیل کرنے والا عذاب ہے",
"""۱۔ جھوٹی قسمیں — اتخذوا أیمانهم جنّة فصدّوا عن سبیل الله؛ فلهم عذاب مهین۔
۲۔ ’’اتَّخَذُوا أَيْمَانَهُمْ جُنَّۃً فَصَدُّوا عَن سَبِيلِ اللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ‘‘ —انہوں نے اپنی قسموں کو ڈھال بنایا اور اللہ کے راستے سے روکا پس ان کے لیے ذلیل کرنے والا عذاب ہے۔
۳۔ عملی سبق: جھوٹی قسمیں نہ کھاؤ؛ اللہ سے ڈرو۔"""
),
5121: (
"نہ ان کا مال ان کے کام آئے گا نہ ان کی اولاد اللہ سے کچھ بھی — یہی آگ والے ہیں — وہ اس میں ہمیشہ رہیں گے",
"""۱۔ بہت کچھ بے فائدہ — لن تغني عنهم أموالهم و لا أولادهم من الله شیئًا؛ أولئک أصحاب النار؛ هم فیها خالدون۔
۲۔ ’’لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ‘‘ — نہ ان کا مال ان کے کام آئے گا نہ ان کی اولاد اللہ سے کچھ بھی — یہی آگ والے ہیں — وہ اس میں ہمیشہ رہیں گے — یعنی نہ ان کا مال ان کے کام آئے گا نہ ان کی اولاد اللہ سے کچھ بھی یہی آگ والے ہیں وہ اس میں ہمیشہ رہیں گے۔
۳۔ عملی سبق: مال اور اولاد پر فریب نہ کھاؤ؛ اللہ سے ڈرو۔"""
),
5122: (
"جس دن اللہ سب کو اٹھائے گا پس وہ اس کے سامنے قسمیں کھائیں گے جیسے تمہارے سامنے قسمیں کھاتے ہیں — اور وہ گمان کرتے ہیں کہ وہ کسی چیز پر ہیں — خبردار بے شک وہی جھوٹے ہیں",
"""۱۔ قیامت کا حال — یوم یبعثهم الله جمیعًا فیحلفون له کما یحلفون لکم؛ و یحسبون أنهم علی شيء؛ ألا إنهم هم الکاذبون۔
۲۔ ’’يَوْمَ يَبْعَثُهُمُ اللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَيْءٍ أَلَا إِنَّهُمْ هُمُ الْكَاذِبُونَ‘‘ — جس دن اللہ سب کو اٹھائے گا پس وہ اس کے سامنے قسمیں کھائیں گے جیسے تمہارے سامنے قسمیں کھاتے ہیں — اور وہ گمان کرتے ہیں کہ وہ کسی چیز پر ہیں — خبردار بے شک وہی جھوٹے ہیں — یعنی جس دن اللہ سب کو اٹھائے گا پس وہ اس کے سامنے قسمیں کھائیں گے جیسے تمہارے سامنے قسمیں کھاتے ہیں اور وہ گمان کرتے ہیں کہ وہ کسی چیز پر ہیں خبردار بے شک وہی جھوٹے ہیں۔
۳۔ عملی سبق: جھوٹ سے بچو؛ اللہ سے ڈرو۔"""
),
5123: (
"شیطان نے ان پر غلبہ پا لیا پس انہوں نے اللہ کا ذکر بھلا دیا — یہی شیطان کا گروہ ہے — خبردار بے شک شیطان کا گروہ ہی خسارے میں ہے",
"""۱۔ شیطان کا گروہ — استحوذ علیهم الشیطان فأنساهم ذکر الله؛ أولئک حزب الشیطان؛ ألا إن حزب الشیطان هم الخاسرون۔
۲۔ ’’اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ فَأَنسَاهُمْ ذِكْرَ اللَّهِ أُولَٰئِكَ حِزْبُ الشَّيْطَانِ أَلَا إِنَّ حِزْبَ الشَّيْطَانِ هُمُ الْخَاسِرُونَ‘‘ — شیطان نے ان پر غلبہ پا لیا پس انہوں نے اللہ کا ذکر بھلا دیا — یہی شیطان کا گروہ ہے — خبردار بے شک شیطان کا گروہ ہی خسارے میں ہے — یعنی شیطان نے ان پر غلبہ پا لیا پس انہوں نے اللہ کا ذکر بھلا دیا یہی شیطان کا گروہ ہے خبردار بے شک شیطان کا گروہ ہی خسارے میں ہے۔
۳۔ عملی سبق: اللہ کا ذکر کرو؛ شیطان سے بچو؛ اللہ سے ڈرو۔"""
),
5124: (
"بے شک جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں وہی ذلیلوں میں ہیں",
"""۱۔ ذلیل — إن الذین یحادّون الله و رسوله أولئک في الأذلین۔
۲۔ ’’إِنَّ الَّذِينَ يُحَادُّونَ اللَّهَ وَرَسُولَهُ أُولَٰئِكَ فِي الْأَذَلِّينَ‘‘ —بے شک جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں وہی ذلیلوں میں ہیں۔
۳۔ عملی سبق: اللہ اور رسول سے دشمنی نہ کرو؛ اللہ سے ڈرو۔"""
),
5125: (
"اللہ نے لکھ دیا ہے کہ میں اور میرے رسول غالب آئیں گے — بے شک اللہ قوی عزیز ہے",
"""۱۔ اللہ کا وعدہ — کتب الله لأغلبنّ أنا و رسلي؛ إن الله قوي عزیز۔
۲۔ ’’كَتَبَ اللَّهُ لَأَغْلِبَنَّ أَنَا وَرُسُلِي إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ‘‘ — اللہ نے لکھ دیا ہے کہ میں اور میرے رسول غالب آئیں گے — بے شک اللہ قوی عزیز ہے — یعنی اللہ نے لکھ دیا ہے کہ میں اور میرے رسول غالب آئیں گے بے شک اللہ قوی عزیز ہے۔
۳۔ عملی سبق: اللہ کے وعدے پر بھروسہ رکھو؛ اللہ سے ڈرو۔"""
),
5126: (
"تم ایسی قوم نہیں پاؤ گے جو اللہ اور آخرت کے دن پر ایمان رکھتی ہو اور ان سے دوستی رکھتی ہو جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں اگرچہ وہ ان کے باپ ہوں یا ان کے بیٹے یا ان کے بھائی یا ان کے خاندان — یہی وہ ہیں جن کے دلوں میں اس نے ایمان لکھ دیا ہے اور انہیں اپنی روح سے مدد دی ہے — اور انہیں ایسی جنتوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — ہمیشہ ان میں رہیں گے — اللہ ان سے راضی ہوا اور وہ اس سے راضی ہوئے — یہی اللہ کا گروہ ہے — خبردار بے شک اللہ کا گروہ ہی کامیاب ہے",
"""۱۔ اللہ کا گروہ — لا تجد قومًا یؤمنون بالله و الیوم الآخر یوادّون من حادّ الله و رسوله و لو کانوا آباءهم أو أبناءهم أو إخوانهم أو عشیرتهم؛ أولئک کتب في قلوبهم الإیمان و أیّدهم بروح منه؛ و یدخلهم جنات تجري من تحتها الأنهار خالدین فیها؛ رضي الله عنهم و رضوا عنه؛ أولئک حزب الله؛ ألا إن حزب الله هم المفلحون۔
۲۔ ’’لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُم أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ أُولَٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ أُولَٰئِكَ حِزْبُ اللَّهِ أَلَا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ‘‘ — تم ایسی قوم نہیں پاؤ گے جو اللہ اور آخرت کے دن پر ایمان رکھتی ہو اور ان سے دوستی رکھتی ہو جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں اگرچہ وہ ان کے باپ ہوں یا ان کے بیٹے یا ان کے بھائی یا ان کے خاندان — یہی وہ ہیں جن کے دلوں میں اس نے ایمان لکھ دیا ہے اور انہیں اپنی روح سے مدد دی ہے — اور انہیں ایسی جنتوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — ہمیشہ ان میں رہیں گے — اللہ ان سے راضی ہوا اور وہ اس سے راضی ہوئے — یہی اللہ کا گروہ ہے — خبردار بے شک اللہ کا گروہ ہی کامیاب ہے — یعنی تم ایسی قوم نہیں پاؤ گے جو اللہ اور آخرت کے دن پر ایمان رکھتی ہو اور ان سے دوستی رکھتی ہو جو اللہ اور اس کے رسول سے دشمنی کرتے ہیں اگرچہ وہ ان کے باپ ہوں یا ان کے بیٹے یا ان کے بھائی یا ان کے خاندان یہی وہ ہیں جن کے دلوں میں اس نے ایمان لکھ دیا ہے اور انہیں اپنی روح سے مدد دی ہے اور انہیں ایسی جنتوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں ہمیشہ ان میں رہیں گے اللہ ان سے راضی ہوا اور وہ اس سے راضی ہوئے یہی اللہ کا گروہ ہے خبردار بے شک اللہ کا گروہ ہی کامیاب ہے۔
۳۔ عملی سبق: اللہ کے دوستوں سے دوستی رکھو؛ اللہ سے ڈرو۔"""
),
}
